[asy]
path a = (-10*sqrt(2),-10*sqrt(2)--0*sqrt(2),-10*sqrt(2)--0*sqrt(2),0*sqrt(2)--10*sqrt(2),0*sqrt(2)--10*sqrt(2),10*sqrt(2)--0*sqrt(2),10*sqrt(2)--cycle,
 path b = (-10*sqrt(2),8*sqrt(2)---10*sqrt(2),8*sqrt(2)-10*sqrt(2)---4*sqrt(2),-6*sqrt(2)-4*sqrt(2)--0*sqrt(2),-6*sqrt(2)--0*sqrt(2),2*sqrt(2)---4*sqrt(2),2*sqrt(2)+8*sqrt(2)--cycle,
path c=(0,0)--(-10*sqrt(2),10*sqrt(2))--(-15*sqrt(2),-sqrt(2)) (15*sqrt(2),-sqrt(2))--(10*sqrt(2),20*sqrt(2))--(0,30*sqrt(2))--(-10*sqrt(2),10*sqrt(2));
draw(a^^b^^c);dot(a);dot(m);dot((-10*sqrt(2),0));dot((10*sqrt(2),0));dot((0,10*sqrt(2)));dot((0,-10*sqrt(2)));
label("St. Paul",(0,10*sqrt(2)),N);label("M. Minneapolis",(10*sqrt(2),0),E);label(" downtown St. Paul",(-10*sqrt(2),0),W);
draw((-10*sqrt(2),0)--(10*sqrt(2),0),Arrow);draw((0,10*sqrt(2))--(0,-10*sqrt(2)),Arrow);[/asy] By the Pythagorean Theorem, the distance is $\boxed{13}$ miles.<answer>13</answer>

